def check_xor(data):
    for key in range(0x20, 0x7F):  # ASCII printable keys
        decrypted = bytes([b ^ key for b in data])
        if b'csawctf{' in decrypted:
            return decrypted
    return None

def check_base64(data):
    try:
        decoded = base64.b64decode(data)
        if b'csawctf{' in decoded:
            return decoded
    except base64.binascii.Error:
        pass
    return None

